// Yardımcı کلاسları içe aktar
"src/utils/validation.hudhud" استفاده;
"src/utils/formatting.hudhud" استفاده;

چاپ("============================================================");
چاپ("E-Ticaret Sistemi - Modüler Mimari Demo");
چاپ("============================================================\n");

// Servis örnekleri oluştur
متغیر authService = جدید AuthService();
متغیر paymentService = جدید PaymentService();
متغیر notificationService = جدید NotificationService();

چاپ("1️⃣  KULLANICI KAYDI");
چاپ("─────────────────────────────────────────────────────────\n");

// Yeni استفادهıcı oluştur
متغیر newUser = جدید User("Davut Süleyman", "davut@example.com", "güvenli123");
چاپ("Kullanıcı oluşturuldu: " + newUser.bilgi());

// Email درستla
اگر (Validation.email(newUser.email)) {
    چاپ("✓ Email geçerli: " + newUser.email);
} وگرنه {
    چاپ("✗ Email geçersiz");
}

// Kullanıcıyı kaydet
متغیر authResult = authService.register(newUser);
اگر (authResult.success) {
    چاپ("✓ " + authResult.message + " (ID: " + authResult.userId + ")");

    // Hoş geldin bildirimi
    notificationService.send(
        newUser.email,
        "Hoş Geldiniz!",
        "Aramıza hoş geldiniz, " + newUser.name
    );
}

چاپ("\n2️⃣  ÜRÜN OLUŞTURMA");
چاپ("─────────────────────────────────────────────────────────\n");

// Ürün oluştur
متغیر product = جدید Product("MacBook Pro M3", 45000, 10, "Elektronik");
چاپ("Ürün oluşturuldu: " + product.bilgi());

// Fiyat درستla
اگر (Validation.price(product.price)) {
    چاپ("✓ Fiyat geçerli: " + Formatting.currency(product.price, "TRY"));
}

// Stok kontrolü
اگر (product.inStock()) {
    چاپ("✓ Ürün stokta mevcut");
} وگرنه {
    چاپ("✗ Ürün stokta yok");
}

چاپ("\n3️⃣  SİPARİŞ OLUŞTURMA");
چاپ("─────────────────────────────────────────────────────────\n");

// Sipariş oluştur
متغیر order = جدید Order(
    newUser.id,
    product.id,
    1,
    product.price
);
چاپ("Sipariş oluşturuldu: " + order.bilgi());

چاپ("\n4️⃣  ÖDEME İŞLEMİ");
چاپ("─────────────────────────────────────────────────────────\n");

// Ödeme işle
متغیر paymentResult = paymentService.process(
    order.id,
    order.totalPrice,
    "credit_card"
);

اگر (paymentResult.success) {
    چاپ("✓ " + paymentResult.message);
    چاپ("  İşlem No: " + paymentResult.transactionId);
    چاپ("  Tutar: " + Formatting.currency(paymentResult.amount, "TRY"));
    چاپ("  Yöntem: " + paymentResult.method);

    // Siparişi onayla
    order.confirm();
    چاپ("✓ Sipariş onaylandı: " + order.status);

    // Sipariş onay bildirimi
    notificationService.send(
        newUser.email,
        "Siparişiniz Onaylandı",
        "Sipariş numaranız: " + order.id + " - Toplam: " + Formatting.currency(order.totalPrice, "TRY")
    );
} وگرنه {
    چاپ("✗ Ödeme başarısız: " + paymentResult.error);
}

چاپ("\n============================================================");
چاپ("✓ E-Ticaret sistemi demo tamamlandı!");
چاپ("✓ Modüler, ölçeklenebilir ve bakımı kolay mimari");
چاپ("============================================================");

