// Payment Service - Ödeme Servisi

کلاس PaymentService {
    تابع process(orderId, amount, method) {
        // Basitleştirilmiş ödeme işlemi
        متغیر success = درست; // Gerçekte API çağrısı yapılır

        اگر (success) {
            برگشت {
                success: درست,
                transactionId: "TXN_" + Math.floor(Math.random() * 100000),
                amount: amount,
                method: method,
                message: "Ödeme başarılı"
            };
        } وگرنه {
            برگشت {
                success: نادرست,
                error: "Ödeme başarısız"
            };
        }
    }

    تابع refund(transactionId) {
        برگشت {
            success: درست,
            refundId: "REF_" + Math.floor(Math.random() * 100000)
        };
    }
}

