// Order Model - Sipariş Modeli

کلاس Order {
    سازنده(userId, productId, quantity, totalPrice) {
        خود.id = Math.floor(Math.random() * 10000);
        خود.userId = userId;
        خود.productId = productId;
        خود.quantity = quantity;
        خود.totalPrice = totalPrice;
        خود.status = "pending";
        خود.createdAt = "2024-03-07";
    }

    تابع bilgi() {
        برگشت "Sipariş #" + خود.id + " - Kullanıcı: " + خود.userId + ", Ürün: " + خود.productId + ", Adet: " + خود.quantity + ", Toplam: " + خود.totalPrice + " TL, Durum: " + خود.status;
    }

    تابع confirm() {
        خود.status = "confirmed";
    }

    تابع getId() {
        برگشت خود.id;
    }
}

