// Formatting Utilities - Formatlama Fonksiyonları

کلاس Formatting {
    ثابت تابع currency(amount, currency) {
        اگر (currency == "TRY") {
            برگشت amount + " ₺";
        } وگرنه {
            اگر (currency == "USD") {
                برگشت "$" + amount;
            } وگرنه {
                اگر (currency == "EUR") {
                    برگشت "€" + amount;
                } وگرنه {
                    برگشت amount + " " + currency;
                }
            }
        }
    }

    ثابت تابع date(date) {
        برگشت date;
    }

    ثابت تابع phone(phone) {
        // (555) 123-4567 formatı
        برگشت "(" + phone + ")";
    }

    ثابت تابع number(num) {
        // 1,234,567 formatı
        برگشت num;
    }
}

files.src/utils/validation.hudhud:
// Validation Utilities - Doğrulama Fonksiyonları

کلاس Validation {
    ثابت تابع email(email) {
        // Basit email درستlama
        برگشت email.length > 5;
    }

    ثابت تابع password(password) {
        // Şifre en az 6 karakter olmalı
        برگشت password.length >= 6;
    }

    ثابت تابع price(price) {
        برگشت price > 0;
    }

    ثابت تابع phone(phone) {
        // Telefon numarası درستlama
        برگشت phone.length == 10;
    }

    ثابت تابع required(value) {
        برگشت value.length > 0;
    }
}

