// Formatting Utilities - Formatlama Fonksiyonları

کلاس Formatting {
    ثابت تابع currency(amount, currency) {
        اگر (currency == "TRY") {
            برگشت amount + " ₺";
        } وگرنه {
            اگر (currency == "USD") {
                برگشت "$" + amount;
            } وگرنه {
                اگر (currency == "EUR") {
                    برگشت "€" + amount;
                } وگرنه {
                    برگشت amount + " " + currency;
                }
            }
        }
    }

    ثابت تابع date(date) {
        برگشت date;
    }

    ثابت تابع phone(phone) {
        // (555) 123-4567 formatı
        برگشت "(" + phone + ")";
    }

    ثابت تابع number(num) {
        // 1,234,567 formatı
        برگشت num;
    }
}

